thead[is="tree-view-table-header"] {
  block-size: var(--tree-header-table-height);
  position: sticky;
  inset-inline: 0;
  inset-block-start: 0;
  z-index: 1;

  &::after {
    content: "";
    position: absolute;
    inset-inline: 0;
    block-size: 0;
    z-index: 1;
    border-block-end: 1px solid var(--sidebar-border);
  }
}

th[is="tree-view-table-header-cell"] {
  block-size: var(--tree-header-table-height);
  min-inline-size: 5ch;
  padding: 0;
  position: relative;
  overflow: hidden;
  background-color: var(--layout-background-1);

